<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{{ $name }} · Budget & Forecast</title><style>body{font:16px system-ui;background:#f6f7fb;color:#182139;margin:0;padding:32px}.report{max-width:1000px;margin:auto;background:white;border:1px solid #dce1eb;border-radius:24px;padding:32px}h1{font-size:32px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:16px}.tile{padding:22px;border-radius:18px;background:linear-gradient(135deg,#173d83,#538ff5);color:white}.tile:nth-child(2){background:linear-gradient(135deg,#512b89,#9a6bf2)}.tile:nth-child(3){background:linear-gradient(135deg,#075953,#31a99b)}strong{display:block;font-size:26px;margin-top:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #e4e7ef}.muted{color:#67718a;font-size:14px}.bar{height:8px;background:#3454ef;border-radius:10px}img{max-height:60px;max-width:180px}</style></head><body><main class="report">@if(!empty($payload['report_brand']['logo'])&&preg_match('~^https?://~i',$payload['report_brand']['logo']))<img src="{{ $payload['report_brand']['logo'] }}" alt="{{ $payload['report_brand']['name'] }}">@endif<p class="muted">Budget & Forecast · read-only snapshot · {{ $created }}</p><h1>{{ $name }}</h1><p>{{ $payload['company']??'' }} · {{ $forecast['period'] }} month planning horizon</p><div class="grid">@foreach(['spend'=>'Modelled cost','revenue'=>'Forecast revenue','contribution'=>'Forecast contribution'] as $k=>$label)<div class="tile">{{ $label }}<strong>₹{{ number_format($forecast['totals'][$k],0) }}</strong></div>@endforeach</div><p class="muted">Forecasts use the author’s assumptions. Contribution = revenue after gross margin minus modelled marketing costs; it is not net business profit. No live advertising attribution is implied. Values below use INR.</p><h2>Channel allocation</h2><tabl